import math
from fractions import Fraction

def is_perfect_square(n):
    if n < 0:
        return False
    # Use integer square root for precision
    sqrt_n = math.isqrt(n)
    return sqrt_n * sqrt_n == n

def find_solutions_N3():
    solutions = set()
    K = [-2, -1, 0, 1, 2]

    for k1 in K:
        for k2 in K:
            for k3 in K:
                if k1 == 0 and k2 == 0 and k3 == 0:
                    continue

                if k3 == 0:
                    # Linear case: k1 + k2*p = 0
                    if k2 != 0:
                        p = Fraction(-k1, k2)
                        if p > 0:
                            solutions.add(p)
                else:
                    # Quadratic case: k3*p^2 + k2*p + k1 = 0
                    # Discriminant: D = k2^2 - 4*k3*k1
                    D = k2**2 - 4 * k3 * k1

                    if D < 0:
                        continue

                    if is_perfect_square(D):
                        m = math.isqrt(D)

                        # Root 1: p = (-k2 + m) / (2*k3)
                        # Use Fraction constructor for rational representation
                        p1_num = -k2 + m
                        p1_den = 2 * k3
                        p1 = Fraction(p1_num, p1_den)

                        # Root 2: p = (-k2 - m) / (2*k3)
                        p2_num = -k2 - m
                        p2_den = 2 * k3
                        p2 = Fraction(p2_num, p2_den)

                        # Check for positivity
                        if p1 > 0:
                            solutions.add(p1)
                        if p2 > 0:
                            solutions.add(p2)

    return sorted(list(solutions))

results = find_solutions_N3()

